import { test } from 'node:test';
import {spawn} from 'node:child_process';
test('standalone node package pairs, edits actual isolated files and returns a signed result',{skip:!process.env.JARVIS_NODE_PACKAGE},async()=>{
 const f=await fixture(),configPath=join(f.directory,'packaged-agent.json');let child:ReturnType<typeof spawn>|undefined;
 try{
  await writeFile(configPath,JSON.stringify({apiUrl:f.url,machineId:f.machineId,pairingTicket:f.runtime.issueTicket(f.machineId,['fixture']).ticket,workspaceRoots:[f.root],templates:[f.template]}));
  await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');
  child=spawn(process.execPath,[resolve(process.env.JARVIS_NODE_PACKAGE!), '--config',configPath],{shell:false,windowsHide:true,stdio:'ignore'});
  for(let i=0;i<100&&!f.runtime.listRuns()[0]?.result;i++)await new Promise(r=>setTimeout(r,100));
  assert.equal(f.runtime.listRuns()[0].status,'succeeded');assert.ok((await readFile(join(f.workspace,'result.txt'),'utf8')).includes(f.repo.read('tasks',f.taskId,'server-admin')!.goal));assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.status,'validating');
  const saved=JSON.parse(await readFile(configPath,'utf8'));assert.ok(saved.agentId);assert.ok(saved.privateKey);assert.equal(saved.pairingTicket,undefined);
 }finally{if(child&&child.exitCode===null){const closed=new Promise<void>(r=>child!.once('close',()=>r()));child.kill('SIGTERM');await closed}await f.close()}
});
const nativeRecoveryPolicy={billing:'subscription' as const,maxTokens:10000,maxRecoveryAttempts:2,retryDelaySec:60,repairValidation:true,fallbackExecutorIds:['native-claude']};
async function nativeRecoveryFixture(){
 const f=await fixture();const codexScript=join(f.tools,'quota-codex.cjs'),claudeScript=join(f.tools,'quota-claude.cjs');
 await writeFile(codexScript,`console.log(JSON.stringify({type:'thread.started',thread_id:'codex-original-session'}));console.log(JSON.stringify({type:'turn.completed',turn_id:'quota-turn',usage:{input_tokens:37,output_tokens:5,cached_input_tokens:0}}));console.log(JSON.stringify({type:'error',message:'Usage limit reached 429'}));process.exit(1)`);
 await writeFile(claudeScript,`console.log(JSON.stringify({type:'system',subtype:'init',session_id:'claude-specific-session',claude_code_version:'2.1.277'}));console.log(JSON.stringify({type:'result',session_id:'claude-specific-session',is_error:true,errors:['Rate limit reached 429'],total_cost_usd:0,usage:{input_tokens:0,output_tokens:0}}));`);
 const codex:ExecutionTemplate={...f.template,id:'native-codex',engine:'codex',args:[codexScript,'exec','--json','--sandbox','workspace-write','{prompt}'],supervision:nativeRecoveryPolicy},claude:ExecutionTemplate={...f.template,id:'native-claude',engine:'claude',args:[claudeScript,'--print','{prompt}','--output-format','stream-json','--max-budget-usd','{maxBudgetUSD}'],supervision:{...nativeRecoveryPolicy,fallbackExecutorIds:['native-codex']}};
 f.runtime.configure({templates:[codex,claude]});const update:DomainHandler={domain:'tasks',commands:['fixture-native'],execute:(_c,p,ctx)=>ctx.update('tasks',f.taskId,p)};
 const patch=(p:any)=>{const task=f.repo.read('tasks',f.taskId,'server-admin')!;return f.repo.execute(update,'fixture-native',{commandId:randomUUID(),expectedVersion:task.revision,scope:'personal',payload:p},'server-admin',f.runtime.options.machine).data};patch({agent:codex.id});
 const agent=new ExecutionAgent({apiUrl:f.url,machineId:f.machineId,pairingTicket:f.runtime.issueTicket(f.machineId,[codex.id,claude.id]).ticket,workspaceRoots:[f.root],templates:[codex,claude]});await agent.pair();await agent.heartbeat();
 const due=()=>{const task=f.repo.read('tasks',f.taskId,'server-admin')!;return patch({executionResult:{...task.executionResult,recovery:{...task.executionResult.recovery,retryAt:new Date(Date.now()-1000).toISOString()}}})};
 return {...f,codex,claude,nativeAgent:agent,patch,due,async close(){await agent.stop();await f.close()}};
}

test('durable quota recovery switches only the authorized same-workspace native executor, stops at the limit and never auto-accepts',async()=>{
 const f=await nativeRecoveryFixture();try{
  const originalResult=f.runtime.result.bind(f.runtime);(f.runtime as any).result=async(agentId:string,body:any)=>{try{return await originalResult(agentId,body)}catch(error){const e=error as any;console.error('SYNTHETIC_RESULT_REJECTION',JSON.stringify({code:e.code??'UNKNOWN',message:e.message??'rejected',fields:e.details?.fields??[]}));throw error}};
  f.repo.setReceiptValidator((domain,r)=>{if(domain==='tasks')assertDto('Task',r.data)});
  await (f.runtime as any).scheduleManaged();const first=await f.nativeAgent.runOnce();assert.equal(first.status,'failed');let task=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(task.status,'waitingQuota');assert.equal(task.executionResult.recovery.nextExecutorId,f.claude.id);assert.equal(task.sessionId,'codex-original-session');assert.equal(task.acceptance,null);
  f.due();let supervised=false;f.runtime.options.supervised=()=>supervised;await (f.runtime as any).scheduleManaged();assert.equal(f.runtime.listRuns().length,1);supervised=true;
  await Promise.all([(f.runtime as any).scheduleManaged(),(f.runtime as any).scheduleManaged()]);assert.equal(f.runtime.listRuns().length,2);task=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(task.agent,f.claude.id);assert.equal(task.sessionId,null);assert.equal(task.executionRequest.workspace,f.workspace);assert.equal(task.executionRequest.handoff.executorId,f.codex.id);
  await f.nativeAgent.runOnce();task=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(task.executionResult.recovery.attempts,2);assert.equal(task.executionResult.recovery.nextExecutorId,undefined,'recent quota failure on Codex must not ping-pong');assert.equal(task.status,'waitingQuota');
  f.due();await (f.runtime as any).scheduleManaged();await f.nativeAgent.runOnce();task=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(task.executionResult.recovery.attempts,3);assert.equal(task.executionResult.recovery.automatic,false);assert.equal(task.status,'failed');await (f.runtime as any).scheduleManaged();assert.equal(f.runtime.listRuns().length,3);assert.equal(task.acceptance,null);
  assert.equal((await f.app.inject({method:'GET',url:'/api/v1/execution/supervision'})).statusCode,401);const state=await f.app.inject({method:'GET',url:'/api/v1/execution/supervision',headers:{cookie:'jarvis_session=fixture'}});assert.equal(state.statusCode,200);assert.equal(state.json().data.tasks[0].tokenLimit,10000);
 }finally{await f.close()}
});

test('revoked recovery configuration and expired task deadlines wait for the owner without executing',async()=>{
 for(const reason of ['revoked','deadline'] as const){const f=await nativeRecoveryFixture();try{
  await (f.runtime as any).scheduleManaged();await f.nativeAgent.runOnce();f.due();
  if(reason==='revoked')f.runtime.configure({templates:[{...f.codex,supervision:{...nativeRecoveryPolicy,maxRecoveryAttempts:0}},f.claude]});else f.patch({deadline:new Date(Date.now()-1000).toISOString()});
  await (f.runtime as any).scheduleManaged();assert.equal(f.runtime.listRuns().length,1);assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.status,'waitingUser');
 }finally{await f.close()}}
});

test('API-priced unreported quota consumption cannot automatically retry and a node refuses changed executable policies',async()=>{
 const f=await nativeRecoveryFixture();try{
  const priced={...f.codex,supervision:{...nativeRecoveryPolicy,billing:'priced' as const}};f.runtime.configure({templates:[priced,f.claude]});f.nativeAgent.config.templates[0]=priced;await (f.runtime as any).scheduleManaged();await f.nativeAgent.runOnce();const task=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(task.executionResult.recovery.automatic,false);assert.equal(task.status,'failed');assert.equal(f.runtime.listRuns().length,1);
 }finally{await f.close()}
 const g=await nativeRecoveryFixture();try{await (g.runtime as any).scheduleManaged();const claim=await g.nativeAgent.claim();g.nativeAgent.config.templates[0]={...g.codex,maxRounds:4};await assert.rejects(()=>g.nativeAgent.execute(claim!),/AGENT_TEMPLATE_MISMATCH/);assert.equal(g.runtime.getRun(claim!.id)!.status,'running');assert.equal(g.repo.read('tasks',g.taskId,'server-admin')!.acceptance,null)}finally{await g.close()}
});
