test('signed NAS heartbeat stores data-volume detail and replaces incorrect root-disk totals',async()=>{
 const f=await fixture();try{
  const machine=f.repo.read('machines',f.machineId,'server-admin')!;
  const patch:DomainHandler={domain:'machines',commands:['nas-fixture'],execute:(_c,_p,ctx)=>ctx.update('machines',f.machineId,{category:'storage',source:'manual',verification:'unverified_external',executionDispatched:false,createdAt:ctx.now,updatedAt:ctx.now})};
  f.repo.execute(patch,'nas-fixture',{commandId:randomUUID(),expectedVersion:machine.revision,scope:'personal',payload:{}},'server-admin',f.runtime.options.machine);
  f.repo.setReceiptValidator((domain,receipt)=>{if(domain==='machines')assertDto('InfrastructureRecord',receipt.data);});
  const keys=generateKeyPairSync('ed25519'),agent=f.runtime.pair(f.runtime.issueTicket(f.machineId,['telemetry']).ticket,keys.publicKey.export({format:'pem',type:'spki'}).toString());
  const path=`/api/v1/agents/${agent.agentId}/heartbeat`;
  const send=(body:any)=>{const timestamp=new Date().toISOString(),nonce=randomBytes(24).toString('base64url'),signature=sign(null,Buffer.from(signedExecutionText('POST',path,timestamp,nonce,body)),keys.privateKey).toString('base64url');return f.app.inject({method:'POST',url:path,payload:body,headers:{'x-jarvis-timestamp':timestamp,'x-jarvis-nonce':nonce,'x-jarvis-signature':signature}});};
  const body={metrics:{diskTotalGB:.4,diskPercent:99,diskFreeGB:0},storage:{kind:'qnap',model:'TS-453Dmini',systemVersion:'5.2.6',build:'20250715',observedAt:new Date().toISOString(),disks:[],volumes:[{id:1,mount:'/share/CACHEDEV1_DATA',totalGB:600,usedGB:60,freeGB:535},{id:2,mount:'/share/CACHEDEV2_DATA',totalGB:7200,usedGB:3600,freeGB:3500}]}};
  assert.equal((await send(body)).statusCode,200);
  const saved=f.repo.read('machines',f.machineId,'server-admin')!;
  assert.equal(saved.telemetry.diskTotalGB,7800);assert.equal(saved.telemetry.diskFreeGB,4035);assert.equal(saved.telemetry.storage.volumes.length,2);assert.equal(saved.agentStatus,'connected');
  assert.equal((await send({...body,storage:{...body.storage,volumes:[{...body.storage.volumes[0],mount:'/'}]}})).statusCode,400);
  assert.equal(f.repo.read('machines',f.machineId,'server-admin')!.lastSeen,saved.lastSeen);
  assert.equal((await send({metrics:{memoryTotalGB:7.6}})).statusCode,200);
  assert.equal(Object.hasOwn(f.repo.read('machines',f.machineId,'server-admin')!.telemetry,'storage'),false);
 }finally{await f.close();}
});

async function fixture(supervised=true){const directory=await mkdtemp(join(tmpdir(),'jarvis-execution-')),root=join(directory,'workspaces'),workspace=join(root,'project'),tools=join(directory,'tools');await mkdir(workspace,{recursive:true});await mkdir(tools);await writeFile(join(tools,'run.cjs'),`const fs=require('node:fs');fs.writeFileSync('result.txt',process.argv[2]||'actual child process');console.log(JSON.stringify({type:'execution.result',summary:'actual isolated fixture process',artifacts:['result.txt'],usage:{inputTokens:0,outputTokens:0,costUSD:0,costKind:'provider-reported'}}));`);const store=new Store(join(directory,'data')),repo=new V1Repository(store.databasePath),machineId=randomUUID(),projectId=randomUUID(),taskId=randomUUID();const template:ExecutionTemplate={id:'fixture',machineId,engine:'fixed',program:process.execPath,args:[join(tools,'run.cjs'),'{prompt}'],workspaceRoot:root,maxRounds:3,timeoutSec:20,leaseSec:10,budgetCurrency:'USD'};let stopped=false;const usage:any[]=[];const runtime=new ExecutionRuntime(repo,{directory:join(directory,'runtime'),machine:id=>id==='local'?{id:'local',status:'online'}:repo.read('machines',id,'server-admin'),stopped:()=>stopped,supervised:()=>supervised,onUsage:u=>{usage.push(u)}});const seed:DomainHandler={domain:'machines',commands:['fixture'],execute:(_c,_p,ctx)=>{const machine=ctx.create('machines',{kind:'machine',name:'isolated fixture node',status:'unknown',ram:64,readOnly:false},machineId);ctx.create('projects',{name:'fixture project',status:'active',copies:[{machineId,path:workspace,environment:'test',branch:'main'}]},projectId);ctx.create('tasks',{title:'fixture task',projectId,machineId,agent:'fixture',mode:'managed',goal:'Actual fixture process $(must stay literal)',criteria:'independent review required',status:'queued',progress:0,budget:10,cost:0,retryLimit:2,retries:0,dependsOn:null,deadline:null,sessionId:null,lease:null,artifacts:[],acceptance:null,skillRefs:[],updatedAt:ctx.now,externalReports:[],resumeStatus:null},taskId);return machine}};repo.execute(seed,'fixture',{commandId:randomUUID(),expectedVersion:0,scope:'personal',payload:{}},'server-admin',()=>undefined);runtime.configure({templates:[template]});const app=Fastify({logger:false,bodyLimit:128*1024});await app.register(cookie);app.addHook('onRequest',async(req,reply)=>{if(!isExecutionProtocolPath(req.method,req.url.split('?')[0])&&req.cookies.jarvis_session!=='fixture')return reply.code(401).send({code:'FORBIDDEN'})});app.setErrorHandler((e:any,_r,reply)=>reply.code(e.status??e.statusCode??400).send({code:e.code??'VALIDATION',message:e.message}));registerExecutionRoutes(app,runtime,token=>token==='fixture');await app.listen({host:'127.0.0.1',port:0});const address=app.server.address();assert.ok(address&&typeof address==='object');const url=`http://127.0.0.1:${address.port}`,ticket=runtime.issueTicket(machineId,['fixture']).ticket,agent=new ExecutionAgent({apiUrl:url,machineId,pairingTicket:ticket,workspaceRoots:[root],templates:[template]});await agent.pair();await agent.heartbeat();const commandId=randomUUID(),envelope={commandId,expectedVersion:1,scope:'personal' as const,payload:{taskId}};return {directory,root,workspace,tools,store,repo,runtime,app,agent,machineId,projectId,taskId,template,url,ticket,envelope,usage,stop(){stopped=true},async close(){await agent.stop();await app.close();await runtime.close();repo.close();store.close();const absolute=resolve(directory);assert.ok(absolute.startsWith(resolve(tmpdir())+sep)&&absolute.includes('jarvis-execution-'));await rm(absolute,{recursive:true,force:true})}}}

test('signed paired agent executes an actual isolated child process, records logs/usage and awaits independent acceptance',async()=>{const f=await fixture();try{const receipt=await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');assert.equal(receipt!.data.status,'queued');assert.equal(receipt!.data.executionStatus,'queued');assert.equal(receipt!.data.lease,null);assert.equal(f.repo.read('machines',f.machineId,'server-admin')!.status,'online');const result=await f.agent.runOnce();assert.equal(result.status,'succeeded');assert.match(await readFile(join(f.workspace,'result.txt'),'utf8'),/\$\(must stay literal\)/);const task=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(task.status,'validating');assert.equal(task.acceptance,null);assert.equal(task.lease,null);assert.equal(task.cost,0);assert.equal(task.costCurrency,'USD');assert.deepEqual(task.artifacts,['result.txt']);assert.equal(f.usage.length,1);assert.equal(f.usage[0].usage.inputTokens,0);assert.ok(f.runtime.logs(result.id).some(l=>String(l.text).includes('actual isolated fixture process')));assert.deepEqual(await f.runtime.dispatch('tasks','start',f.envelope,'server-admin'),receipt,'same command id replays after execution status changes');assert.equal(f.runtime.listRuns().length,1)}finally{await f.close()}});

test('native quota result through strict DTO routes preserves partial observed tokens and an unknown cost',async()=>{const f=await fixture();try{const template:ExecutionTemplate={...f.template,id:'fixture',engine:'claude',program:process.execPath,args:[join(f.tools,'run.cjs'),'--print','{prompt}','--output-format','stream-json'],supervision:{billing:'record-only',maxTokens:10000,maxRecoveryAttempts:0,retryDelaySec:60,repairValidation:false,fallbackExecutorIds:[]}};f.runtime.configure({templates:[template]});f.agent.config.templates=[template];const update:DomainHandler={domain:'tasks',commands:['native-update'],execute:(_c,_p,ctx)=>ctx.update('tasks',f.taskId,{agent:template.id,goal:'Inspect actual task',criteria:'retain unknown spend safely'})};const task=f.repo.execute(update,'native-update',{commandId:randomUUID(),expectedVersion:1,scope:'personal',payload:{}},'server-admin',f.runtime.options.machine).data;const queued=await f.runtime.dispatch('tasks','start',{commandId:randomUUID(),expectedVersion:task.revision,scope:'personal',payload:{taskId:f.taskId}},'server-admin');const claim=await f.agent.claim();assert.ok(claim);const route=`/api/v1/agents/${f.agent.config.agentId}/result`,body={deliveryId:randomUUID(),runId:claim!.id,leaseToken:claim!.leaseToken,outcome:'failed',exitCode:1,rounds:1,summary:'quota observed',usage:{inputTokens:19,outputTokens:2,totalTokens:21,usageComplete:false,measurementStatus:'partial',costComplete:false,provider:'claude-cli',model:'fixture-model'},sessionId:'fixture-session',sessionBilling:{engine:'claude',sessionId:'fixture-session',costUSD:0.03,nativeCliVersion:'fixture-cli-1',costScope:'session-cumulative'}};const timestamp=new Date().toISOString(),nonce=randomBytes(24).toString('base64url'),signature=sign(null,Buffer.from(signedExecutionText('POST',route,timestamp,nonce,body)),f.agent.config.privateKey!).toString('base64url'),headers={'x-jarvis-timestamp':timestamp,'x-jarvis-nonce':nonce,'x-jarvis-signature':signature};assert.equal(validateDto('ExecutionResultInput',{runId:claim!.id,leaseToken:claim!.leaseToken,outcome:body.outcome,exitCode:1,rounds:1,summary:'quota observed',usage:body.usage,sessionId:body.sessionId,sessionBilling:body.sessionBilling,deliveryId:body.deliveryId}).valid,true);const response=await f.app.inject({method:'POST',url:route,payload:body,headers});assert.equal(response.statusCode,200,response.body);const taskAfter=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(taskAfter.executionResult.usage.inputTokens,19);assert.equal(taskAfter.executionResult.usage.outputTokens,2);assert.equal(taskAfter.executionResult.usage.usageComplete,false);assert.equal(taskAfter.executionResult.usage.costComplete,false);assert.equal(taskAfter.executionResult.usage.costUSD,undefined);assert.equal(taskAfter.executionResult.sessionBilling.nativeCliVersion,'fixture-cli-1');assert.equal(taskAfter.executionResult.sessionBilling.costScope,'session-cumulative');assert.equal(f.runtime.getRun(queued!.data.executionRequest.id)!.status,'failed');const replay=await f.app.inject({method:'POST',url:route,payload:body,headers});assert.equal(replay.statusCode,403,'signed nonces must not replay a result request; outbox delivery replay uses a fresh signed request');}finally{await f.close()}});

test('pairing ticket is one-use, signatures bind body/path and nonces cannot replay',async()=>{const f=await fixture();try{assert.throws(()=>f.runtime.pair(f.ticket,f.agent.config.publicKey!),/票据/);const id=f.agent.config.agentId!,timestamp=new Date().toISOString(),nonce=randomBytes(24).toString('base64url'),path=`/api/v1/agents/${id}/heartbeat`,body={metrics:{cpuPercent:2}},signature=sign(null,Buffer.from(signedExecutionText('POST',path,timestamp,nonce,body)),f.agent.config.privateKey!).toString('base64url');const headers={'x-jarvis-timestamp':timestamp,'x-jarvis-nonce':nonce,'x-jarvis-signature':signature};assert.equal((await f.app.inject({method:'POST',url:path,headers,payload:body})).statusCode,200);assert.equal((await f.app.inject({method:'POST',url:path,headers,payload:body})).statusCode,403);assert.equal((await f.app.inject({method:'POST',url:path,headers:{...headers,'x-jarvis-nonce':randomBytes(24).toString('base64url')},payload:{metrics:{cpuPercent:100}}})).statusCode,403);assert.equal((await f.app.inject({url:'/api/v1/execution/agents'})).statusCode,401);const inventory=(await f.app.inject({url:'/api/v1/execution/agents',headers:{cookie:'jarvis_session=fixture'}})).json();assert.equal(JSON.stringify(inventory).includes('PRIVATE KEY'),false);assert.equal(JSON.stringify(inventory).includes('PUBLIC KEY'),false);f.runtime.revoke(id);await assert.rejects(()=>f.agent.heartbeat(),/403/)}finally{await f.close()}});

test('expired lease interrupts without repeating execution; late receipts cannot restore running state',async()=>{const f=await fixture();try{const receipt=await f.runtime.dispatch('tasks','start',f.envelope,'server-admin'),claim=await f.agent.claim();assert.ok(claim);assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.status,'running');const db=(f.runtime as any).db;db.prepare('UPDATE execution_runs SET lease_expires=? WHERE id=?').run(new Date(Date.now()-1000).toISOString(),receipt!.data.executionRequest.id);f.runtime.reconcile();assert.equal(f.runtime.getRun(claim!.id)!.status,'interrupted');assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.status,'paused');assert.throws(()=>f.runtime.appendLogs(f.agent.config.agentId!,{runId:claim!.id,leaseToken:claim!.leaseToken,entries:[{channel:'stdout',text:'late'}]}),/租约/);assert.equal(await f.agent.claim(),null);assert.equal(f.runtime.listRuns().length,1)}finally{await f.close()}});

test('changed templates, emergency stop, revisions and directory escape are enforced before any process',async()=>{const f=await fixture();try{await assert.rejects(()=>checkedAgentWorkspace(f.tools,[f.root]),/OUTSIDE/);assert.throws(()=>f.runtime.configure({templates:[{...f.template,program:'C:\\Windows\\System32\\cmd.exe',args:['/c','bad']}]}),/shell/);await assert.rejects(()=>f.runtime.dispatch('tasks','start',{...f.envelope,expectedVersion:999},'server-admin'),/记录已更新/);await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');f.runtime.configure({templates:[{...f.template,args:[join(f.tools,'run.cjs'),'changed']}]});await assert.rejects(()=>f.agent.claim(),/409/);await assert.rejects(readFile(join(f.workspace,'result.txt')));f.stop();f.runtime.reconcile();assert.equal(f.runtime.listRuns()[0].status,'cancelled');assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.status,'paused')}finally{await f.close()}});

test('actual project file backup and isolated restore compare every SHA256 without overwriting the workspace',async()=>{const f=await fixture();try{await writeFile(join(f.workspace,'book.txt'),'original source');f.runtime.configure({templates:[f.template,{...f.template,id:'local-backup',machineId:'local'}]});const backups=new ExecutionBackups(f.runtime);const backup=await backups.create({sourcePath:f.workspace,machineId:'local',target:'projects',scope:'personal'});assert.equal(backup.data.verification,'hash-verified-copy');assert.equal(backup.data.manifest.files.length,1);await writeFile(join(f.workspace,'book.txt'),'current changed source');const drill=await backups.drill(backup.data.id);assert.equal(drill.data.restoration.outcome,'pass');assert.equal(drill.data.restoration.productionOverwritten,false);assert.equal(await readFile(join(drill.data.restoration.restoreTarget,'book.txt'),'utf8'),'original source');assert.equal(await readFile(join(f.workspace,'book.txt'),'utf8'),'current changed source');await writeFile(join(f.workspace,'running.sqlite'),'not a safe live DB copy');await assert.rejects(()=>backups.create({sourcePath:f.workspace,machineId:'local',target:'projects',scope:'personal'}),/一致性备份/)}finally{await f.close()}});

test('fixed child process timeout actually stops process and redacts secrets before logs leave the node',async()=>{const f=await fixture();try{const path=join(f.tools,'long.cjs');await writeFile(path,"console.log('token=do-not-export-this-value');console.log(JSON.stringify({access_token:'do-not-export-json-token',refresh_token:'do-not-export-refresh-token',private_key:'do-not-export-private-key'}));setInterval(()=>{},100);");const logs:string[]=[];const before=Date.now(),result=await executeFixedProcess(process.execPath,[path],f.workspace,new AbortController().signal,5,(_c,text)=>logs.push(text));assert.equal(result.timedOut,true);assert.ok(Date.now()-before<20000);assert.equal(logs.some(l=>l.includes('do-not-export')),false);assert.ok(logs.some(l=>l.includes('[REDACTED]')))}finally{await f.close()}});

test('approved deployment and rollback actually run fixed programs, verify backup hash and update only the fixed observed version',async()=>{const f=await fixture();try{const serviceId=randomUUID(),deploymentId=randomUUID(),approvalId=randomUUID(),backupId=randomUUID(),releaseId=randomUUID(),backupPath=join(f.root,'version.backup');await writeFile(backupPath,'0.9.0');await writeFile(join(f.workspace,'version.txt'),'0.9.0');const checksum='sha256:'+createHash('sha256').update('0.9.0').digest('hex');const deployScript=join(f.tools,'deploy.cjs'),restoreScript=join(f.tools,'restore.cjs'),checkScript=join(f.tools,'check.cjs');await writeFile(deployScript,"const fs=require('node:fs');fs.writeFileSync('version.txt',process.argv[2]);console.log(JSON.stringify({type:'execution.result',summary:'fixed deployment executed',artifacts:['version.txt']}));");await writeFile(restoreScript,"const fs=require('node:fs');fs.writeFileSync('version.txt',fs.readFileSync(process.argv[2],'utf8'));console.log(JSON.stringify({type:'execution.result',summary:'fixed rollback executed',artifacts:['version.txt']}));");await writeFile(checkScript,"const fs=require('node:fs');const observedVersion=fs.readFileSync('version.txt','utf8');console.log(JSON.stringify({observedVersion}));process.exit(observedVersion===process.argv[2]?0:1);");const deploy:ExecutionTemplate={...f.template,id:`deploy:${serviceId}`,args:[deployScript,'{version}'],maxRounds:1,validation:{program:process.execPath,args:[checkScript,'{version}'],timeoutSec:10}},restore:ExecutionTemplate={...deploy,id:`restore:${serviceId}`,args:[restoreScript,'{backupPath}']};f.runtime.configure({templates:[f.template,deploy,restore]});const handler:DomainHandler={domain:'operations',commands:['fixture-deployment'],execute:(_c,_p,ctx)=>{ctx.update('projects',f.projectId,{copies:[{machineId:f.machineId,path:f.workspace,environment:'production',branch:'release'}]});ctx.create('services',{kind:'service',machineId:f.machineId,projectId:f.projectId,environment:'production',version:'0.9.0',name:'actual fixture service'},serviceId);ctx.create('releases',{projectId:f.projectId,version:'1.0.0'},releaseId);ctx.create('operations',{kind:'backup',machineId:f.machineId,status:'registered',locator:backupPath,checksum},backupId);ctx.create('approvals',{kind:'deployment',deploymentId,backupId,status:'approved',decision:{authorizedDeploymentId:deploymentId}},approvalId);return ctx.create('operations',{kind:'deployment',status:'approved',serviceId,releaseId,backupId,approvalId,machineId:f.machineId,projectId:f.projectId,environment:'production',version:'1.0.0',previousVersion:'0.9.0'},deploymentId)}};f.repo.execute(handler,'fixture-deployment',{commandId:randomUUID(),expectedVersion:0,scope:'personal',payload:{}},'server-admin',f.runtime.options.machine);const agent=new ExecutionAgent({apiUrl:f.url,machineId:f.machineId,pairingTicket:f.runtime.issueTicket(f.machineId,[deploy.id,restore.id]).ticket,workspaceRoots:[f.root],backupRoots:[f.root],templates:[deploy,restore]});await agent.pair();await agent.heartbeat();const request={commandId:randomUUID(),expectedVersion:1,scope:'personal' as const,payload:{deploymentId}};const aliasRequest={commandId:randomUUID(),expectedVersion:1,scope:'personal' as const,payload:{approvalId,reason:'执行此固定申请'}};const aliasReceipt=await f.runtime.dispatch('approvals','execute',aliasRequest,'server-admin');assert.equal(aliasReceipt!.data.id,approvalId);const deployed=await agent.runOnce();assert.deepEqual(await f.runtime.dispatch('approvals','execute',aliasRequest,'server-admin'),aliasReceipt);assert.equal(deployed.status,'succeeded');assert.equal(await readFile(join(f.workspace,'version.txt'),'utf8'),'1.0.0');assert.equal(f.repo.read('services',serviceId,'server-admin')!.version,'1.0.0');const d=f.repo.read('operations',deploymentId,'server-admin')!;assert.equal(d.status,'deployed');await assert.rejects(()=>f.runtime.dispatch('services','execute',{...request,commandId:randomUUID(),expectedVersion:d.revision},'server-admin'),/不能重复/);await assert.rejects(()=>f.runtime.dispatch('approvals','rollback',{commandId:randomUUID(),expectedVersion:1,scope:'personal',payload:{approvalId,reason:'不可扩大恢复范围',snapshotId:randomUUID()}},'server-admin'),/恢复点/);await f.runtime.dispatch('approvals','rollback',{commandId:randomUUID(),expectedVersion:1,scope:'personal',payload:{approvalId,reason:'恢复固定原版本',snapshotId:backupId}},'server-admin');const restored=await agent.runOnce();assert.equal(restored.status,'succeeded');assert.equal(await readFile(join(f.workspace,'version.txt'),'utf8'),'0.9.0');assert.equal(f.repo.read('services',serviceId,'server-admin')!.version,'0.9.0');assert.equal(f.repo.read('operations',deploymentId,'server-admin')!.status,'restored');assert.equal(f.runtime.listRuns().length,2)}finally{await f.close()}});

test('native SDK hook is bounded by rounds and keeps ledgerRecorded usage out of double billing',async()=>{const f=await fixture();try{let calls=0;f.runtime.options.runPi=async input=>{assert.equal(input.workspace,f.workspace);assert.ok(input.maxBudgetUSD>0);calls++;await writeFile(join(f.workspace,'sdk.txt'),`round ${calls}`);return {text:JSON.stringify({summary:'still needs work',needs_more_work:true}),usage:{inputTokens:2,outputTokens:3,costUSD:0.01,costKind:'catalog-estimate',ledgerRecorded:true},artifacts:['sdk.txt']}};f.runtime.options.piReady=()=>true;const sdk:ExecutionTemplate={...f.template,id:'pi',machineId:'local',engine:'pi-sdk',maxRounds:2};delete sdk.program;delete sdk.args;f.runtime.configure({templates:[sdk]});const adjust:DomainHandler={domain:'tasks',commands:['fixture-sdk'],execute:(_c,_p,ctx)=>{ctx.update('projects',f.projectId,{copies:[{machineId:'local',path:f.workspace,environment:'test',branch:'main'}]});return ctx.update('tasks',f.taskId,{machineId:'local',agent:'pi'})}};const task=f.repo.execute(adjust,'fixture-sdk',{commandId:randomUUID(),expectedVersion:1,scope:'personal',payload:{}},'server-admin',f.runtime.options.machine).data;await f.runtime.dispatch('tasks','start',{...f.envelope,expectedVersion:task.revision},'server-admin');for(let i=0;i<100&&f.runtime.listRuns()[0]?.status!=='round-limit';i++)await new Promise(r=>setTimeout(r,20));assert.equal(calls,2);assert.equal(f.runtime.listRuns()[0].status,'round-limit');assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.status,'blocked');assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.acceptance,null);assert.equal(f.usage.length,1);assert.equal(f.usage[0].usage.ledgerRecorded,true);assert.equal(f.usage[0].usage.costUSD,0.02)}finally{await f.close()}});

test('trusted SDK partial usage charges failed budgets and cancelled late receipts cannot overwrite a resumed run',async()=>{
 for(const mode of ['failure','cancel-resume'] as const){const f=await fixture(false);try{
  let release!:()=>void,started!:()=>void;const startedPromise=new Promise<void>(r=>{started=r}),releasePromise=new Promise<void>(r=>{release=r});f.runtime.options.runPi=async()=>{started();if(mode==='cancel-resume')await releasePromise;throw new PiDevelopmentFailure('isolated SDK failure',{inputTokens:7,outputTokens:3,costUSD:mode==='failure'?10:0.25,costKind:'catalog-estimate',ledgerRecorded:true})};f.runtime.options.piReady=()=>true;let reserved=0,released=0;f.runtime.options.beforeExecution=()=>{reserved++};f.runtime.options.afterExecution=()=>{released++};const sdk:ExecutionTemplate={...f.template,id:'pi-partial',machineId:'local',engine:'pi-sdk',maxRounds:1};delete sdk.program;delete sdk.args;f.runtime.configure({templates:[sdk]});const adjust:DomainHandler={domain:'tasks',commands:['fixture-partial'],execute:(_c,_p,ctx)=>{ctx.update('projects',f.projectId,{copies:[{machineId:'local',path:f.workspace,environment:'test',branch:'main'}]});return ctx.update('tasks',f.taskId,{machineId:'local',agent:sdk.id})}};const task=f.repo.execute(adjust,'fixture-partial',{commandId:randomUUID(),expectedVersion:1,scope:'personal',payload:{}},'server-admin',f.runtime.options.machine).data;const receipt=await f.runtime.dispatch('tasks','start',{...f.envelope,expectedVersion:task.revision},'server-admin');const id=receipt!.data.executionRequest.id;await startedPromise;
  let resumedId:string|undefined;if(mode==='cancel-resume'){f.runtime.cancelRun(id,'isolated administrator stop');const paused=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(paused.status,'paused');const resumed=await f.runtime.dispatch('tasks','resume',{commandId:randomUUID(),expectedVersion:paused.revision,scope:'personal',payload:{taskId:f.taskId}},'server-admin');resumedId=resumed!.data.executionRequest.id;assert.notEqual(resumedId,id);release();}
  for(let i=0;i<300&&!f.runtime.getRun(id)?.result;i++)await new Promise(r=>setTimeout(r,10));const current=f.repo.read('tasks',f.taskId,'server-admin')!;assert.equal(current.cost,mode==='failure'?10:0.25);assert.equal(current.costKind,'catalog-estimate');assert.equal(f.usage.length,1);assert.equal(f.usage[0].usage.ledgerRecorded,true);assert.equal(reserved,0);assert.equal(released,0);
  if(mode==='failure'){assert.equal(current.status,'failed');await assert.rejects(()=>f.runtime.dispatch('tasks','retry',{commandId:randomUUID(),expectedVersion:current.revision,scope:'personal',payload:{taskId:f.taskId}},'server-admin'),/预算耗尽/);}else{assert.equal(current.executionRequest.id,resumedId);assert.equal(current.executionStatus,'queued');assert.equal(current.status,'queued');assert.equal(f.runtime.getRun(resumedId!)!.status,'queued');assert.equal(f.runtime.getRun(id)!.status,'cancelled');}
 }finally{await f.close()}}
});
