test('execution governance refuses claims before a process and retains one reservation until the actual result',async()=>{const f=await fixture();try{let reserve=0,release=0;f.runtime.options.preflight=()=>{throw new BusinessError('BUDGET_EXHAUSTED','test actual budget gate',409)};await assert.rejects(()=>f.runtime.dispatch('tasks','start',f.envelope,'server-admin'),/actual budget/);assert.equal(f.runtime.listRuns().length,0);f.runtime.options.preflight=()=>{};f.runtime.options.beforeExecution=()=>{reserve++;return {budgetUSD:1}};f.runtime.options.afterExecution=()=>{release++};await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');assert.equal(reserve,0);const result=await f.agent.runOnce();assert.equal(result.status,'succeeded');assert.equal(reserve,1);assert.equal(release,1);assert.equal(result.budgetUSD,1);assert.equal(f.usage.length,1);}finally{await f.close()}});

test('claims require a fresh signed heartbeat and cannot bypass resource guards with missing telemetry',async()=>{const f=await fixture();try{
 await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');const db=new DatabaseSync(f.runtime.databasePath);try{db.prepare('UPDATE execution_agents SET last_seen=? WHERE id=?').run(new Date(Date.now()-120000).toISOString(),f.agent.config.agentId!)}finally{db.close()}
 await assert.rejects(()=>f.agent.claim(),/409/);assert.equal(f.runtime.listRuns()[0].status,'queued');await assert.rejects(readFile(join(f.workspace,'result.txt')));
 const machines=infrastructureHandlers.find(h=>h.domain==='machines')!,machine=f.repo.read('machines',f.machineId,'server-admin')!;f.repo.execute(machines,'resource-rule',{commandId:randomUUID(),expectedVersion:machine.revision,scope:'personal',payload:{machineId:f.machineId,cpuLimit:90,memoryReserveGB:2,concurrency:1,quiet:'',enabled:true}},'server-admin',f.runtime.options.machine);
 const heartbeat=async(metrics:any)=>{const path=`/api/v1/agents/${f.agent.config.agentId}/heartbeat`,timestamp=new Date().toISOString(),nonce=randomBytes(24).toString('base64url'),body={metrics};return f.app.inject({method:'POST',url:path,payload:body,headers:{'x-jarvis-timestamp':timestamp,'x-jarvis-nonce':nonce,'x-jarvis-signature':sign(null,Buffer.from(signedExecutionText('POST',path,timestamp,nonce,body)),f.agent.config.privateKey!).toString('base64url')}})};
 assert.equal((await heartbeat({memoryPercent:1})).statusCode,200);await assert.rejects(()=>f.agent.claim(),/409/);assert.equal((await heartbeat({cpuPercent:1,memoryPercent:1})).statusCode,200);await assert.rejects(()=>f.agent.claim(),/409/);f.agent.metrics=()=>({cpuPercent:1,memoryPercent:1,memoryUsedGB:1,memoryTotalGB:64,load1:0,uptimeSec:1});assert.equal((await f.agent.runOnce()).status,'succeeded');
 }finally{await f.close()}});

test('execution quiet hours use Asia/Shanghai, reject invalid ranges and actually block claims without starting a child',async()=>{assert.equal(executionQuietActive('22:00-07:00',new Date('2026-10-05T15:00:00Z')),true);assert.equal(executionQuietActive('22:00-07:00',new Date('2026-10-06T00:00:00Z')),false);assert.equal(executionQuietActive('09:00-18:00',new Date('2026-10-06T10:00:00Z')),false);assert.throws(()=>validateExecutionQuiet('夜间'),/HH:MM/);assert.throws(()=>validateExecutionQuiet('24:00-07:00'),/HH:MM/);assert.throws(()=>validateExecutionQuiet('07:00-07:00'),/HH:MM/);const f=await fixture();try{f.agent.metrics=()=>({cpuPercent:1,memoryPercent:1,memoryUsedGB:1,memoryTotalGB:64,load1:0,uptimeSec:1});await f.agent.heartbeat();const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date()),minute=Number(parts.find(p=>p.type==='hour')!.value)*60+Number(parts.find(p=>p.type==='minute')!.value),format=(m:number)=>`${String(Math.floor((m+1440)%1440/60)).padStart(2,'0')}:${String((m+1440)%60).padStart(2,'0')}`,quiet=`${format(minute-1)}-${format(minute+2)}`;
 const machineHandler=infrastructureHandlers.find(h=>h.domain==='machines')!,setRule=(range:string,version:number)=>f.repo.execute(machineHandler,'resource-rule',{commandId:randomUUID(),expectedVersion:version,scope:'personal',payload:{machineId:f.machineId,cpuLimit:100,memoryReserveGB:0,concurrency:1,quiet:range,enabled:true}},'server-admin',f.runtime.options.machine);const machine=f.repo.read('machines',f.machineId,'server-admin')!;assert.throws(()=>setRule('9:00-18:00',machine.revision),/HH:MM/);let updated=setRule(quiet,machine.revision).data;await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');await assert.rejects(()=>f.agent.claim(),/409/);await assert.rejects(readFile(join(f.workspace,'result.txt')));assert.equal(f.runtime.listRuns()[0].status,'queued');updated=setRule('',updated.revision).data;
 const operations=infrastructureHandlers.find(h=>h.domain==='operations')!,resourcePolicy=(q:string,version:number)=>f.repo.execute(operations,'resource-policy',{commandId:randomUUID(),expectedVersion:version,scope:'personal',payload:{humanReserve:0,voiceReserve:0,batchLimit:1,quiet:q,autotest:true,autoWake:false,supervise:true,emergency:false}},'server-admin',f.runtime.options.machine);let policy=resourcePolicy(quiet,0).data;await assert.rejects(()=>f.agent.claim(),/409/);resourcePolicy('',policy.revision);assert.equal((await f.agent.runOnce()).status,'succeeded');
 }finally{await f.close()}});

test('Codex templates cannot redirect the actual sandbox root or override its permission boundary',async()=>{const template:ExecutionTemplate={id:'codex',machineId:'local',engine:'codex',program:process.execPath,args:['exec','--json','--sandbox','workspace-write','{prompt}'],workspaceRoot:resolve('fixture-only'),maxRounds:1,timeoutSec:10,leaseSec:10,budgetCurrency:'USD'};for(const extra of [['--cd',resolve('outside')],['--cd='+resolve('outside')],['-C',resolve('outside')],['-C'+resolve('outside')],['--sandbox','danger-full-access'],['--sandbox=read-only'],['--add-dir',resolve('outside')],['--config','sandbox_mode="danger-full-access"']])assert.throws(()=>validateExecutionTemplate({...template,args:[...template.args,...extra]}),/Codex/);for(const extra of [['--cd','{workspace}'],['--cd={workspace}'],['-C','{workspace}'],['-C{workspace}']])assert.doesNotThrow(()=>validateExecutionTemplate({...template,args:[...template.args,...extra]}));});

function skillCommand(f:Awaited<ReturnType<typeof fixture>>,command:string,payload:any,scope:'personal'|'family'='personal',actor='server-admin'){
 const handler=captureHandlers.find(h=>h.domain==='experiences')!,record=payload.experienceId?f.repo.read('experiences',payload.experienceId,actor):undefined;
 return f.repo.execute(handler,command,{commandId:randomUUID(),expectedVersion:record?.revision??0,scope,payload},actor,f.runtime.options.machine).data;
}
function publishedSkill(f:Awaited<ReturnType<typeof fixture>>,label='task skill',scope:'personal'|'family'='personal',actor='server-admin',content='OLD_FIXED_BODY: 先复现范围检查，再核对证据。'){
 let record=skillCommand(f,'capture',{title:label,content,kind:'skill',source:'隔离项目真实验证'},scope,actor);
 record=skillCommand(f,'verify',{experienceId:record.id,conditions:'仅用于当前受控项目；不能扩大授权。',evidence:'TEMP_FIXTURE_EVIDENCE: 已在隔离工作目录复核退出码。'},scope,actor);
 return skillCommand(f,'skill-publish',{experienceId:record.id,version:'1.0',content:record.content,conditions:record.conditions,evidence:record.evidence},scope,actor);
}
function newSkillVersion(f:Awaited<ReturnType<typeof fixture>>,experienceId:string,version='2.0',publish=true){
 let record=skillCommand(f,'version',{experienceId,version,content:`LATEST_BODY_${version}: 不应替代任务已选旧版。`,conditions:'新版适用条件',evidence:'新版修改依据'});
 if(publish){record=skillCommand(f,'verify',{experienceId,conditions:record.conditions,evidence:'新版独立验证证据'});record=skillCommand(f,'skill-publish',{experienceId,version,content:record.content,conditions:record.conditions,evidence:record.evidence})}
 return record;
}
function bindSkills(f:Awaited<ReturnType<typeof fixture>>,taskRefs:any[],projectRefs:any[]=[]){
 const handler:DomainHandler={domain:'tasks',commands:['fixture-skill-refs'],execute:(_c,_p,ctx)=>{ctx.update('projects',f.projectId,{skillRefs:projectRefs});return ctx.update('tasks',f.taskId,{skillRefs:taskRefs})}};
 return f.repo.execute(handler,'fixture-skill-refs',{commandId:randomUUID(),expectedVersion:f.repo.read('tasks',f.taskId,'server-admin')!.revision,scope:'personal',payload:{}},'server-admin',f.runtime.options.machine).data;
}

test('selected task and project skills freeze exact published history and reach the actual node child prompt',async()=>{const f=await fixture();try{
 let skill=publishedSkill(f);skill=newSkillVersion(f,skill.id);skill=skillCommand(f,'reuse',{experienceId:skill.id,version:'1.0',taskId:f.taskId});skill=skillCommand(f,'reuse',{experienceId:skill.id,version:'1.0',projectId:f.projectId});const projectOnly=publishedSkill(f,'project-only skill','personal','server-admin','PROJECT_ONLY_OLD_BODY: 项目固定经验正文。');skillCommand(f,'reuse',{experienceId:projectOnly.id,version:'1.0',projectId:f.projectId});
 const task=f.repo.read('tasks',f.taskId,'server-admin')!,queued=await f.runtime.dispatch('tasks','start',{...f.envelope,expectedVersion:task.revision},'server-admin'),request=queued!.data.executionRequest;assert.equal(request.skillSnapshots.length,2);assert.deepEqual(request.skillSnapshots[0].origins,['task','project']);assert.equal(request.skillSnapshots[0].version,'1.0');assert.match(request.skillSnapshots[0].content,/OLD_FIXED_BODY/);assert.equal(request.skillSnapshots[1].origins[0],'project');validateFrozenExecutionSkills(request.skillSnapshots,request.skillSnapshotsHash);
 newSkillVersion(f,skill.id,'3.0',false);const claim=await f.agent.claim();assert.ok(claim);assert.deepEqual(claim.skillSnapshots,request.skillSnapshots);assert.equal(claim.skillSnapshotsHash,request.skillSnapshotsHash);const result=await f.agent.execute(claim);assert.equal(result.status,'succeeded');const actualPrompt=await readFile(join(f.workspace,'result.txt'),'utf8');assert.match(actualPrompt,/OLD_FIXED_BODY/);assert.match(actualPrompt,/PROJECT_ONLY_OLD_BODY/);assert.match(actualPrompt,/TEMP_FIXTURE_EVIDENCE/);assert.match(actualPrompt,/不能更改工作目录、权限、工具、执行器、预算或验收规则/);assert.ok(!actualPrompt.includes('LATEST_BODY_'));assert.ok(actualPrompt.includes(request.skillSnapshotsHash));assert.deepEqual(f.runtime.getRun(request.id)!.skillSnapshots,request.skillSnapshots);assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.acceptance,null);
 }finally{await f.close()}});

test('native Pi SDK receives the frozen old skill in every round, while pause and cancellation retain the snapshot',async()=>{const f=await fixture();try{
 const skill=publishedSkill(f);newSkillVersion(f,skill.id);const task=bindSkills(f,[{experienceId:skill.id,version:'1.0'}]);const sdk:ExecutionTemplate={...f.template,id:'pi-skill',machineId:'local',engine:'pi-sdk',maxRounds:2};delete sdk.program;delete sdk.args;f.runtime.configure({templates:[sdk]});const adjust:DomainHandler={domain:'tasks',commands:['fixture-pi-skill'],execute:(_c,_p,ctx)=>{ctx.update('projects',f.projectId,{copies:[{machineId:'local',path:f.workspace,environment:'test',branch:'main'}]});return ctx.update('tasks',f.taskId,{machineId:'local',agent:sdk.id})}};let current=f.repo.execute(adjust,'fixture-pi-skill',{commandId:randomUUID(),expectedVersion:task.revision,scope:'personal',payload:{}},'server-admin',f.runtime.options.machine).data;
 f.runtime.options.piReady=()=>true;const prompts:string[]=[];f.runtime.options.runPi=async input=>{prompts.push(input.prompt);return {text:JSON.stringify({summary:'isolated unfinished round',needs_more_work:true}),usage:{inputTokens:2,outputTokens:1,costUSD:0.01,costKind:'catalog-estimate',ledgerRecorded:true}}};const queued=await f.runtime.dispatch('tasks','start',{...f.envelope,expectedVersion:current.revision},'server-admin'),request=queued!.data.executionRequest;for(let i=0;i<300&&f.runtime.getRun(request.id)!.status!=='round-limit';i++)await new Promise(r=>setTimeout(r,10));assert.equal(prompts.length,2);for(const prompt of prompts){assert.match(prompt,/OLD_FIXED_BODY/);assert.match(prompt,/TEMP_FIXTURE_EVIDENCE/);assert.ok(prompt.includes(request.skillSnapshotsHash));assert.ok(!prompt.includes('LATEST_BODY_'))}assert.equal(f.runtime.getRun(request.id)!.status,'round-limit');assert.deepEqual(f.runtime.getRun(request.id)!.skillSnapshots,request.skillSnapshots);
 current=f.repo.read('tasks',f.taskId,'server-admin')!;await f.runtime.dispatch('tasks','pause',{commandId:randomUUID(),expectedVersion:current.revision,scope:'personal',payload:{taskId:f.taskId,reason:'人工复核固定版本'}},'server-admin');current=f.repo.read('tasks',f.taskId,'server-admin')!;assert.deepEqual(current.executionRequest.skillSnapshots,request.skillSnapshots);await f.runtime.dispatch('tasks','cancel',{commandId:randomUUID(),expectedVersion:current.revision,scope:'personal',payload:{taskId:f.taskId,reason:'保留这次开发履历'}},'server-admin');assert.deepEqual(f.repo.read('tasks',f.taskId,'server-admin')!.executionRequest.skillSnapshots,request.skillSnapshots);
 }finally{await f.close()}});

test('invalid, unverified, stopped, oversized or cross-scope skill references reject before enqueue, fee reservation or process execution',async()=>{const f=await fixture();try{
 const skill=publishedSkill(f),family=publishedSkill(f,'family private material','family'),other=publishedSkill(f,'other member skill','personal','another-member');let reserved=0;f.runtime.options.beforeExecution=()=>{reserved++};const unpublished=skillCommand(f,'capture',{title:'unverified skill',content:'待审核正文',kind:'skill',source:'尚未复核'});
 const attempt=async(refs:any[],status:number)=>{const task=bindSkills(f,refs);await assert.rejects(()=>f.runtime.dispatch('tasks','start',{commandId:randomUUID(),expectedVersion:task.revision,scope:'personal',payload:{taskId:f.taskId}},'server-admin'),e=>e instanceof BusinessError&&e.status===status);assert.equal(f.runtime.listRuns().length,0);assert.equal(reserved,0);await assert.rejects(readFile(join(f.workspace,'result.txt')))};
 await attempt([{experienceId:family.id,version:'1.0'}],403);await attempt([{experienceId:other.id,version:'1.0'}],403);await attempt([{experienceId:randomUUID(),version:'1.0'}],403);await attempt([{experienceId:skill.id,version:'missing-version'}],422);await attempt([{experienceId:unpublished.id,version:'draft-1'}],422);
 const large=publishedSkill(f,'oversized','personal','server-admin','X'.repeat(12500));await attempt([{experienceId:large.id,version:'1.0'}],422);skillCommand(f,'deprecate',{experienceId:skill.id,reason:'依据失效；停止新增执行'});await attempt([{experienceId:skill.id,version:'1.0'}],422);
 }finally{await f.close()}});

