async function signedDelivery(f:Awaited<ReturnType<typeof fixture>>,kind:'logs'|'result',body:any){const path=`/api/v1/agents/${f.agent.config.agentId}/${kind}`,timestamp=new Date().toISOString(),nonce=randomBytes(24).toString('base64url'),signature=sign(null,Buffer.from(signedExecutionText('POST',path,timestamp,nonce,body)),f.agent.config.privateKey!).toString('base64url');return fetch(f.url+path,{method:'POST',headers:{'content-type':'application/json','x-jarvis-timestamp':timestamp,'x-jarvis-nonce':nonce,'x-jarvis-signature':signature},body:canonicalExecution(body)});}
test('durable signed delivery replays exact final/log confirmations after response loss without duplicate usage or business progress',async()=>{const f=await fixture();try{
 await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');const run=(await f.agent.claim())!;
 const log={deliveryId:randomUUID(),runId:run.id,leaseToken:run.leaseToken,entries:[{channel:'stdout',text:'Actual isolated log api_key=private-fixture'}]};
 const firstLog=await (await signedDelivery(f,'logs',log)).json() as any;assert.equal(firstLog.data.accepted,1);
 const result={deliveryId:randomUUID(),runId:run.id,leaseToken:run.leaseToken,outcome:'success',exitCode:0,rounds:1,summary:'Observed isolated completion',artifacts:[],usage:{inputTokens:3,outputTokens:2,costUSD:.01,costKind:'catalog-estimate',usageComplete:true},stopReason:{code:'NODE_STOP',at:new Date().toISOString()}};
 const first=(await (await signedDelivery(f,'result',result)).json() as any).data,task=f.repo.read('tasks',f.taskId,'server-admin')!;
 const replay=(await (await signedDelivery(f,'result',result)).json() as any).data;assert.deepEqual(replay,first);assert.equal(f.usage.length,1);assert.equal(f.usage[0].runId,run.id);assert.equal(f.repo.read('tasks',f.taskId,'server-admin')!.revision,task.revision);assert.equal(task.status,'validating');assert.equal(task.acceptance,null);
 assert.deepEqual((await (await signedDelivery(f,'logs',log)).json() as any).data,firstLog.data);assert.equal(f.runtime.logs(run.id).length,1);assert.match(String(f.runtime.logs(run.id)[0].text),/\[REDACTED\]/);
 assert.equal((await signedDelivery(f,'result',{...result,summary:'altered'})).status,409);assert.equal((await signedDelivery(f,'logs',{...log,entries:[{channel:'stdout',text:'altered'}]})).status,409);
 const db=(f.runtime as any).db;assert.equal(db.prepare('SELECT count(*) AS n FROM execution_deliveries WHERE run_id=?').get(run.id).n,2);
 }finally{await f.close();}});
