 await f.runtime.dispatch('tasks','start',f.envelope,'server-admin');const run=(await f.agent.claim())!;f.runtime.cancelRun(run.id,'explicit fixture user pause');const task=f.repo.read('tasks',f.taskId,'server-admin')!;(f.runtime as any).db.prepare('UPDATE execution_runs SET lease_expires=? WHERE id=?').run(new Date(Date.now()-1000).toISOString(),run.id);
